def validate_password_reset(cls, code, new_password):
        """
        Validates an unhashed code against a hashed code.
        Once the code has been validated and confirmed
        new_password will replace the old users password
        """
        try:
            code = cls.objects.get(code=code)
        except cls.DoesNotExist:
            raise cls.DoesNotExist('Invalid password reset code')

        if not cls.is_code_expired(code):
            code.confirm_code(new_password)
            return True
        else:
            raise cls.DoesNotExist('Code has expired')

